; ----------------------------------------------------------------------------
; check_EEPROM_sum_TDC_offset_5974
;   analysis [medium]: Compares the shadow sum (A) with EEPROM checksum byte $0EE3. Bad sum: clears $0036, sets
;        $0037-38=$FFFF, sets P1214 and defaults the TDC offset (TDC_REF_OFFSET=0, marker $185A=$BD). Good sum:
;        marker $AC = learned offset valid -> clears P1214; any other marker -> TDC offset defaulted to 0/$BD
;        without a code.
;   called from: RESET_entry
; ----------------------------------------------------------------------------
check_EEPROM_sum_TDC_offset_5974:
	cmpa >tdc_v0EE3                     ; 5974  B1 0E E3      compare A with tdc_v0EE3 | A = sum of shadow bytes from load_EEPROM_shadows; $0EE3 = stored EEPROM checksum
	bne loc_5982                        ; 5977  26 09         if A != tdc_v0EE3 goto loc_5982
	ldaa >TDC_offset_valid_marker       ; 5979  B6 18 5A      A = TDC_offset_valid_marker | $AC in $185A marks a learned/valid TDC offset; $BD = defaulted
	cmpa #$AC                           ; 597C  81 AC         compare A with $AC(172)
	beq loc_59A8                        ; 597E  27 28         if TDC_offset_valid_marker == $AC(172) goto loc_59A8
	bra loc_599B                        ; 5980  20 19         goto loc_599B
loc_5982:
	clr >EEPROM_shadow                  ; 5982  7F 00 36      EEPROM_shadow = 0
	ldd #$FFFF                          ; 5985  CC FF FF      D = $FFFF(65535)
	std <$37                            ; 5988  DD 37         [$37] = D
	brclr <$0B,$80,loc_5992             ; 598A  13 0B 80 04   if [$0B] .7 clear goto loc_5992 | skip re-reporting if code already current and latched (pattern used before every DTC set)
	brset <$2B,$80,loc_599B             ; 598E  12 2B 80 09   if [$2B] .7 set goto loc_599B
loc_5992:
	ldaa #$01                           ; 5992  86 01         A = 1
	ldy #DTC_P1214                      ; 5994  18 CE 52 47   Y = &DTC_P1214
	jsr >DTC_set_clear_farcall          ; 5998  BD 7D A9      report DTC_P1214: A!=0 set / A=0 clear
loc_599B:
	ldd #$0000                          ; 599B  CC 00 00      D = $0000(0)
	std >TDC_REF_OFFSET                 ; 599E  FD 18 58      TDC_REF_OFFSET = D
	ldaa #$BD                           ; 59A1  86 BD         A = $BD(189)
	staa >TDC_offset_valid_marker       ; 59A3  B7 18 5A      TDC_offset_valid_marker = A
	bra loc_59B8                        ; 59A6  20 10         goto loc_59B8
loc_59A8:
	brset <$0B,$80,loc_59B0             ; 59A8  12 0B 80 04   if [$0B] .7 set goto loc_59B0
	brset <$1B,$80,loc_59B8             ; 59AC  12 1B 80 08   if [$1B] .7 set goto loc_59B8
loc_59B0:
	clra                                ; 59B0  4F            A = 0
