	ldx #tbl2D_CRANK_INJ_TIMING_TBL_275B; 59C8  CE 27 5B      X = &tbl2D_CRANK_INJ_TIMING_TBL_275B | OBD1: c3...8c
	jsr >lookup_2D_table                ; 59CB  BD 6D 06      A = 2D lookup tbl2D_CRANK_INJ_TIMING_TBL_275B[A]
	staa >ITS_Cold_Base                 ; 59CE  B7 19 C6      ITS_Cold_Base = A
