;   analysis [high]: Called when the CHECKSUM_ADAPT result does not match $02E9. Clears keep-alive RAM 0000-0044,
;        0100-02E8 (CYL_BAL_ADAPT ...) and 1820-1872, then sets $95.0, which makes diag_P0603 set P0603.
;   called from: RESET_entry
; ----------------------------------------------------------------------------
clear_KAM_5B22:
	ldx #ram_v0000                      ; 5B22  CE 00 00      X = &ram_v0000
	cpx #TDC_TEST_RUNNING               ; 5B25  8C 00 45      compare X with &TDC_TEST_RUNNING
	beq loc_5B34                        ; 5B28  27 0A         if X == &TDC_TEST_RUNNING goto loc_5B34
	ldy #egr_v0044                      ; 5B2A  18 CE 00 44   Y = &egr_v0044
