	rts                                 ; 5B5B  39            return

; ----------------------------------------------------------------------------
; Main_task_scheduler
;   analysis [medium]: Background loop: WAI, then (unless an EEPROM write is pending) verifies the EEPROM shadows.
;        On each tick flag $57.3 it refreshes the DDRA/DDRD/DDRG and IOR config registers, then walks all RAM
;        (0000-03FF, 1820-1FFF) with no-op BSET mask 0. Interleaved with that walk, it sums 2 ROM bytes per 8 RAM
;        bytes, covering bank0 $2006-$FFFF then bank1 $8000-$FFFF. A finished sum not equal to ROM_checksum (an
; ----------------------------------------------------------------------------
Main_task_scheduler:
	ldx #PORTG_PG3_bank_select          ; 5B5C  CE 10 02      X = &PORTG_PG3_bank_select
	bclr $00,x,$08                      ; 5B5F  1D 00 08      PORTG_PG3_bank_select .3 bank select (1=bank1) = 0
	ldx #checksum_skip_AA               ; 5B62  CE 20 06      X = &checksum_skip_AA
	stx >ROM_sum_ptr                    ; 5B65  FF 03 56      ROM_sum_ptr = X
	ldx #ram_v0000                      ; 5B68  CE 00 00      X = &ram_v0000
	stx >ROM_sum_accum                  ; 5B6B  FF 03 54      ROM_sum_accum = X
loc_5B6E:
	wai                                 ; 5B6E  3E            wait for interrupt | background loop: sleep until the next interrupt
	brset <sys_state_flags,$08,loc_5B7E ; 5B6F  12 57 08 0B   if sys_state_flags .3 background tick request set goto loc_5B7E
	brset <sys_state_flags,$02,loc_5B7A ; 5B73  12 57 02 03   if sys_state_flags .1 EEPROM byte rewrite pending ($58/$59) set goto loc_5B7A
	jsr >verify_EEPROM_shadows_5C80     ; 5B77  BD 5C 80      call verify_EEPROM_shadows_5C80
loc_5B7A:
	brclr <sys_state_flags,$08,loc_5B6E ; 5B7A  13 57 08 F0   if sys_state_flags .3 background tick request clear goto loc_5B6E
loc_5B7E:
	bclr <sys_state_flags,$08           ; 5B7E  15 57 08      sys_state_flags .3 background tick request = 0 | periodic refresh: data-direction regs DDRA=$70, DDRD=$3A, DDRG=$EF
	ldx #PORTA                          ; 5B81  CE 10 00      X = &PORTA
	ldy #d_5C72                         ; 5B84  18 CE 5C 72   Y = &d_5C72
	jsr >init_memory_region             ; 5B88  BD 5A 00      call init_memory_region
