loc_5B8E:
	bset $04,x,$00                      ; 5B8E  1C 04 00      [X+4]  = 1 | touch 8 bytes each of 0000-03FF, 1820-1BFF, 1C00-1FFF per step (BSET mask 0 = read/write same value)
	bset $07,x,$00                      ; 5B91  1C 07 00      [X+7]  = 1
	bset $06,x,$00                      ; 5B94  1C 06 00      [X+6]  = 1
