; ----------------------------------------------------------------------------
; calc_ODM_status_hi_5CF7
;   analysis [low]: Reads the ODM fault status over SPI (out_ODM_6D97 A=1, saved in $1BDA/$1BDB). For shift
;        solenoid A and B it builds a 4-bit status (b0 commanded on, b1 off, b2/b3 ODM bit 4/5 fault flags) and
;        runs it through sub_5E1E to update $1BB6 (sol A, used by diag_P0753) and $1BB7 (sol B). Then it runs a
;        second state machine on $1BB9, gated by bits 0/1 of $1BBB and the ODM bit-6 flags.
;   inferred [C, pass A]: writes ODM_status_hi, ODM_shiftA_diag_status, ODM_shiftB_diag_status,
;        ODM_TCC_PWM_diag_status
;   called from: calc_SHIFTPAT_SELECT_90AC
; ----------------------------------------------------------------------------
calc_ODM_status_hi_5CF7:
	ldaa >ODM_TCC_PWM_diag_status       ; 5CF7  B6 1B B9      A = ODM_TCC_PWM_diag_status
	psha                                ; 5CFA  36            push A
	ldaa >PCS_clean_pulse_state         ; 5CFB  B6 1B BB      A = PCS_clean_pulse_state
	psha                                ; 5CFE  36            push A
	ldaa #$01                           ; 5CFF  86 01         A = 1 | read ODM fault status word over SPI
	jsr >ODM_SPI_read_status_6D97       ; 5D01  BD 6D 97      call ODM_SPI_read_status_6D97
	staa >ODM_status_hi                 ; 5D04  B7 1B DA      ODM_status_hi = A
	stab >ram_v1BDB                     ; 5D07  F7 1B DB      ram_v1BDB = B
	pshb                                ; 5D0A  37            push B
	psha                                ; 5D0B  36            push A
	tsx                                 ; 5D0C  30            X = SP + 1
	clrb                                ; 5D0D  5F            B = 0
	ldaa >IOR_1800                      ; 5D0E  B6 18 00      A = IOR_1800 | shift sol A: build status nibble b0 cmd on, b1 cmd off, b2/b3 ODM fault bits
	bita #$10                           ; 5D11  85 10         test IOR_1800 .4 shift solenoid A
	beq loc_5D19                        ; 5D13  27 04         if IOR_1800 .4 shift solenoid A all clear goto loc_5D19
	orab #$01                           ; 5D15  CA 01         B |= 1
	bra loc_5D1B                        ; 5D17  20 02         goto loc_5D1B
loc_5D19:
	orab #$02                           ; 5D19  CA 02         B |= 2
loc_5D1B:
	brclr $01,x,$10,loc_5D21            ; 5D1B  1F 01 10 02   if [X+1] .4 clear goto loc_5D21
	orab #$04                           ; 5D1F  CA 04         B |= 4
loc_5D21:
	brclr $00,x,$10,loc_5D27            ; 5D21  1F 00 10 02   if [X+0] .4 clear goto loc_5D27
	orab #$08                           ; 5D25  CA 08         B |= 8
loc_5D27:
	ldaa >ODM_shiftA_diag_status        ; 5D27  B6 1B B6      A = ODM_shiftA_diag_status
	jsr >sub_5E1E                       ; 5D2A  BD 5E 1E      call sub_5E1E
	staa >ODM_shiftA_diag_status        ; 5D2D  B7 1B B6      ODM_shiftA_diag_status = A
	clrb                                ; 5D30  5F            B = 0
	ldaa >IOR_1800                      ; 5D31  B6 18 00      A = IOR_1800 | same for shift sol B
	bita #$20                           ; 5D34  85 20         test IOR_1800 .5 shift solenoid B
	beq loc_5D3C                        ; 5D36  27 04         if IOR_1800 .5 shift solenoid B all clear goto loc_5D3C
	orab #$01                           ; 5D38  CA 01         B |= 1
	bra loc_5D3E                        ; 5D3A  20 02         goto loc_5D3E
loc_5D3C:
	orab #$02                           ; 5D3C  CA 02         B |= 2
loc_5D3E:
	brclr $01,x,$20,loc_5D44            ; 5D3E  1F 01 20 02   if [X+1] .5 clear goto loc_5D44
	orab #$04                           ; 5D42  CA 04         B |= 4
loc_5D44:
	brclr $00,x,$20,loc_5D4A            ; 5D44  1F 00 20 02   if [X+0] .5 clear goto loc_5D4A
	orab #$08                           ; 5D48  CA 08         B |= 8
loc_5D4A:
	ldaa >ODM_shiftB_diag_status        ; 5D4A  B6 1B B7      A = ODM_shiftB_diag_status
	jsr >sub_5E1E                       ; 5D4D  BD 5E 1E      call sub_5E1E
	staa >ODM_shiftB_diag_status        ; 5D50  B7 1B B7      ODM_shiftB_diag_status = A
	brset $02,x,$01,loc_5D63            ; 5D53  1E 02 01 0C   if [X+2] .0 set goto loc_5D63 | $1BB9 test state machine; idle unless request bits 0/1 of $1BBB set
