	bcs loc_5F0E                        ; 5EB4  25 58         if battery_voltage < $31(49) goto loc_5F0E
	brset <crank_ITS_flags,$08,loc_5ED7 ; 5EB6  12 5A 08 1D   if crank_ITS_flags .3 set goto loc_5ED7
	ldaa >coolant_temp                  ; 5EBA  B6 19 29      A = coolant_temp | first pass: target ITS = crank timing table vs ECT, error = signed half of difference
	ldx #tbl2D_CRANK_INJ_TIMING_TBL_275B; 5EBD  CE 27 5B      X = &tbl2D_CRANK_INJ_TIMING_TBL_275B
	jsr >lookup_2D_table                ; 5EC0  BD 6D 06      A = 2D lookup tbl2D_CRANK_INJ_TIMING_TBL_275B[A]
	staa >ITS_Cold_Base                 ; 5EC3  B7 19 C6      ITS_Cold_Base = A
	suba >ITS_TIMING_POSITION           ; 5EC6  B0 01 19      A -= ITS_TIMING_POSITION
	rora                                ; 5EC9  46            A rotate right thru C
	staa >ITS_ERROR                     ; 5ECA  B7 19 C3      ITS_ERROR = A
	brclr <sys_state_flags,$01,loc_5ED4 ; 5ECD  13 57 01 03   if sys_state_flags .0 clear goto loc_5ED4
