	bne loc_644C                        ; 643F  26 0B         if A != [X+0] goto loc_644C
	brset <$0C,$80,loc_6449             ; 6441  12 0C 80 04   if [$0C] .7 set goto loc_6449
	brset <$1C,$80,loc_647B             ; 6445  12 1C 80 32   if [$1C] .7 set goto loc_647B
