	std >eeprom_v1844                   ; 644F  FD 18 44      eeprom_v1844 = D
	std >eeprom_v1846                   ; 6452  FD 18 46      eeprom_v1846 = D
	std >eeprom_v1848                   ; 6455  FD 18 48      eeprom_v1848 = D
