; TOVFL_SERVICE
;   analysis [high]: Timer-overflow ISR: counts TOVFL_CNT (saturating) and TCNT_EXTENSION, and adds 16 to the high
;        bytes of the trans input shaft and 4K VSS 20-bit timestamp extensions (TCNT is used >>4).
;   OBD1 TOVFL_SERVICE (match 1.00 p1-exact): TOVFL flag interrupt
; ----------------------------------------------------------------------------
TOVFL_SERVICE:
	ldaa >TOVFL_CNT                     ; 652A  B6 19 8B      A = TOVFL_CNT | OBD1: increment TOVFL 1 count
	inca                                ; 652D  4C            A++
	beq loc_6533                        ; 652E  27 03         if A == 0 goto loc_6533
	staa >TOVFL_CNT                     ; 6530  B7 19 8B      TOVFL_CNT = A
loc_6533:
	ldaa >TCNT_EXTENSION                ; 6533  B6 19 D4      A = TCNT_EXTENSION | OBD1: increment rolling timer overflow counter
	inca                                ; 6536  4C            A++
	staa >TCNT_EXTENSION                ; 6537  B7 19 D4      TCNT_EXTENSION = A
	ldaa >TRANS_SHAFT_CTR_EXTENSION     ; 653A  B6 1C 99      A = TRANS_SHAFT_CTR_EXTENSION | OBD1: add 16 to this counter
	adda #$10                           ; 653D  8B 10         A += $10(16)
	staa >TRANS_SHAFT_CTR_EXTENSION     ; 653F  B7 1C 99      TRANS_SHAFT_CTR_EXTENSION = A
	ldaa >VEH_SPD_4K_TCNT               ; 6542  B6 1C B0      A = VEH_SPD_4K_TCNT | OBD1: and add 16 to this counter too
	adda #$10                           ; 6545  8B 10         A += $10(16)
	staa >VEH_SPD_4K_TCNT               ; 6547  B7 1C B0      VEH_SPD_4K_TCNT = A
	ldaa #$80                           ; 654A  86 80         A = $80(128)
	staa >TFLG2                         ; 654C  B7 10 25      TFLG2 = A | OBD1: clear timer overflow flag
	rti                                 ; 654F  3B            return from interrupt

