; STALL_TIMER_RESET
;   analysis [high]: Counts 25 ms ticks in 199A (saturates; reset elsewhere on reference pulses). At >= 13 ticks
;        (~325 ms) without a reference it declares a stall: FLAGS0.4 is set and all RPM variables are zeroed. Sets
;        1474 to RPM_RAW (or 1 when RPM is 0 and still cranking).
;   OBD1 STALL_TIMER_RESET (match 1.00 p1-exact): end of cruise control
;   called from: run_25ms_job
; ----------------------------------------------------------------------------
STALL_TIMER_RESET:
	inc >stall_timer                    ; 8672  7C 19 9A      stall_timer++
	bne loc_867A                        ; 8675  26 03         if stall_timer != 0 goto loc_867A
	dec >stall_timer                    ; 8677  7A 19 9A      stall_timer--
loc_867A:
	ldaa >stall_timer                   ; 867A  B6 19 9A      A = stall_timer | 13 x 25 ms without reference = stalled: zero all RPM variables
	cmpa #$0D                           ; 867D  81 0D         compare A with $0D(13)
	bcs loc_8699                        ; 867F  25 18         if stall_timer < $0D(13) goto loc_8699
	bset <FLAGS0,$10                    ; 8681  14 48 10      FLAGS0 .4 engine stalled (no reference for 325 ms) = 1
	ldd #$0000                          ; 8684  CC 00 00      D = $0000(0)
	std >RPM_RAW                        ; 8687  FD 19 82      RPM_RAW = D
	std >RPM_1                          ; 868A  FD 19 84      RPM_1 = D
	std >engine_RPM                     ; 868D  FD 19 86      engine_RPM = D
	staa >RPM_2_DBL                     ; 8690  B7 19 8A      RPM_2_DBL = A
	std >engine_speed_raw_trans         ; 8693  FD 18 97      engine_speed_raw_trans = D
	std >engine_speed_filtered          ; 8696  FD 18 C7      engine_speed_filtered = D
loc_8699:
	ldx >RPM_RAW                        ; 8699  FE 19 82      X = RPM_RAW
	bne loc_86A7                        ; 869C  26 09         if X != 0 goto loc_86A7
	ldab >STARTUP_CTR                   ; 869E  F6 19 E3      B = STARTUP_CTR
	cmpb >CAL_MIN_CRANK_CYLS            ; 86A1  F1 22 A8      compare B with CAL_MIN_CRANK_CYLS | OBD1: is set to 3
	bhi loc_86A7                        ; 86A4  22 01         if STARTUP_CTR > CAL_MIN_CRANK_CYLS goto loc_86A7
