	ldx #Configuration_set_3_200D       ; 86FF  CE 20 0D      X = &Configuration_set_3_200D
	brclr $00,x,$10,loc_8708            ; 8702  1F 00 10 02   if Configuration_set_3_200D .4 external module data tests clear goto loc_8708 | 200D.4: drop pin A6 (1804.0 PTO) from debounce
