	eora >IN_1804_sample1               ; 870C  B8 1C 88      A ^= IN_1804_sample1
	psha                                ; 870F  36            push A
	tsx                                 ; 8710  30            X = SP + 1
	eorb >IN_1804_sample2               ; 8711  F8 1C 89      B ^= IN_1804_sample2
	orab $00,x                          ; 8714  EA 00         B |= [X+0]
	tba                                 ; 8716  17            A = B
	comb                                ; 8717  53            B = ~B
