	pshx                                ; 87D6  3C            push X
	puly                                ; 87D7  18 38         pop Y
	ldd >engine_speed_filtered          ; 87D9  FC 18 C7      D = engine_speed_filtered
	idiv                                ; 87DC  02            X = D / X, D = remainder
	pshx                                ; 87DD  3C            push X
	pshy                                ; 87DE  18 3C         push Y
	pulx                                ; 87E0  38            pop X
