	xgdx                                ; 87E2  8F            swap D <-> X
	tab                                 ; 87E3  16            B = A
	pula                                ; 87E4  32            pop A
	tsta                                ; 87E5  4D            test A
	bne loc_87EB                        ; 87E6  26 03         if A != 0 goto loc_87EB
	pula                                ; 87E8  32            pop A
	bra loc_87EF                        ; 87E9  20 04         goto loc_87EF
loc_87EB:
	ins                                 ; 87EB  31            SP++
loc_87EC:
	ldd #$FFFF                          ; 87EC  CC FF FF      D = $FFFF(65535)
loc_87EF:
	xgdx                                ; 87EF  8F            swap D <-> X | bands: <0.73 ->3, 0.95-1.05 ->2, 1.25-3.0 ->1, >=3.0 ->0; gaps between are hysteresis (keep gear)
	ldaa #$03                           ; 87F0  86 03         A = 3
	cpx >kw_MT_ratio_g3_max_33DD        ; 87F2  BC 33 DD      compare X with kw_MT_ratio_g3_max_33DD
	bcs loc_8820                        ; 87F5  25 29         if X < kw_MT_ratio_g3_max_33DD goto loc_8820
	cpx >kw_33DF                        ; 87F7  BC 33 DF      compare X with kw_33DF
	bcs loc_8815                        ; 87FA  25 19         if X < kw_33DF goto loc_8815
	deca                                ; 87FC  4A            A--
