	bcs loc_8820                        ; 8800  25 1E         if X < kw_MT_ratio_g2_min_33E1 goto loc_8820
	cpx >kw_33E3                        ; 8802  BC 33 E3      compare X with kw_33E3
	bcs loc_8815                        ; 8805  25 0E         if X < kw_33E3 goto loc_8815
	deca                                ; 8807  4A            A--
	cpx >kw_MT_ratio_g1_max_33E5        ; 8808  BC 33 E5      compare X with kw_MT_ratio_g1_max_33E5
	bcs loc_8820                        ; 880B  25 13         if X < kw_MT_ratio_g1_max_33E5 goto loc_8820
	cpx >kw_33E7                        ; 880D  BC 33 E7      compare X with kw_33E7
	bcs loc_8815                        ; 8810  25 03         if X < kw_33E7 goto loc_8815
	deca                                ; 8812  4A            A--
