	ldab >VEH_SPD_4K_PAICT              ; 8838  F6 1C AD      B = VEH_SPD_4K_PAICT | OBD1: PAI counts
	ldx >VEH_SPD_4K_CT                  ; 883B  FE 1C AE      X = VEH_SPD_4K_CT
