; ----------------------------------------------------------------------------
; calc_delta_vspeed
;   analysis [high]: Filtered vehicle-speed derivative (coef k_342C) in VEH_SPEED_DERIVATIVE. diag_DELTAVSS =
;        deceleration magnitude * 40 (0 when accelerating, FFFF if magnitude >= $0666). Saves vehicle_speed for
;        the next pass.
;   OBD1 calc_delta_vspeed (match 1.00 p1-exact)
;   called from: run_25ms_job
; ----------------------------------------------------------------------------
calc_delta_vspeed:
	ldaa >k_VSS_deriv_filt_coef_342C    ; 89D4  B6 34 2C      A = k_VSS_deriv_filt_coef_342C
	psha                                ; 89D7  36            push A
	ldd >vehicle_speed                  ; 89D8  FC 19 F1      D = vehicle_speed
	subd >LAST_VSPD_FOR_DERIV           ; 89DB  B3 1C A0      D -= LAST_VSPD_FOR_DERIV
	pshb                                ; 89DE  37            push B
	psha                                ; 89DF  36            push A
	ldd >VEH_SPEED_DERIVATIVE           ; 89E0  FC 1C A2      D = VEH_SPEED_DERIVATIVE
	jsr >FILT_16A_signed_6994           ; 89E3  BD 69 94      call FILT_16A_signed_6994
	std >VEH_SPEED_DERIVATIVE           ; 89E6  FD 1C A2      VEH_SPEED_DERIVATIVE = D
	bmi loc_89F0                        ; 89E9  2B 05         if D < 0 (signed) goto loc_89F0 | only deceleration reported; magnitude*40 into diag_DELTAVSS
	ldd #$0000                          ; 89EB  CC 00 00      D = $0000(0)
	bra loc_8A09                        ; 89EE  20 19         goto loc_8A09
loc_89F0:
	coma                                ; 89F0  43            A = ~A
	comb                                ; 89F1  53            B = ~B
	cpd #$0666                          ; 89F2  1A 83 06 66   compare D with $0666(1638)
	bcs loc_89FD                        ; 89F6  25 05         if D < $0666(1638) goto loc_89FD
	ldd #$FFFF                          ; 89F8  CC FF FF      D = $FFFF(65535)
	bra loc_8A09                        ; 89FB  20 0C         goto loc_8A09
loc_89FD:
	asld                                ; 89FD  05            D <<= 1
	asld                                ; 89FE  05            D <<= 1
	asld                                ; 89FF  05            D <<= 1
	pshb                                ; 8A00  37            push B
	psha                                ; 8A01  36            push A
	asld                                ; 8A02  05            D <<= 1
	asld                                ; 8A03  05            D <<= 1
	tsx                                 ; 8A04  30            X = SP + 1
	addd $00,x                          ; 8A05  E3 00         D += [X+0]
	ins                                 ; 8A07  31            SP++
	ins                                 ; 8A08  31            SP++
loc_8A09:
	std >diag_DELTAVSS                  ; 8A09  FD 1A 53      diag_DELTAVSS = D
	ins                                 ; 8A0C  31            SP++
	ins                                 ; 8A0D  31            SP++
	ins                                 ; 8A0E  31            SP++
	ldd >vehicle_speed                  ; 8A0F  FC 19 F1      D = vehicle_speed
	std >LAST_VSPD_FOR_DERIV            ; 8A12  FD 1C A0      LAST_VSPD_FOR_DERIV = D
	rts                                 ; 8A15  39            return

