; ----------------------------------------------------------------------------
; PCS_PWM_output
;   analysis [medium]: Writes the PCS (force motor) duty to PWM 1809 and a copy at $1BAF. A tester device-control
;        override ($1C5B.2 accepted) forces duty 0/FF from $1C5C.2, and 1807.4 forces 0. In gear 0 it runs a
;        force-motor cleaning pulse sequence: low phase kw_4AB8 ticks, then FF phase kw_4ABA ticks, repeated up to
;        k_4AB7 cycles. Otherwise the duty is PCS_duty_cmd.
;   called from: Central_Scheduler
; ----------------------------------------------------------------------------
PCS_PWM_output:
	ldx #devctl_status                  ; 8AB3  CE 1C 59      X = &devctl_status
	ldy #tbl_3865                       ; 8AB6  18 CE 38 65   Y = &tbl_3865
	brclr $02,x,$04,loc_8AC9            ; 8ABA  1F 02 04 0B   if devctl_accepted_mask .2 tester PCS on/off override accepted clear goto loc_8AC9 | tester device control of PCS: accepted ($1C5B.2) -> duty FF or 0 per requested state $1C5C.2
	brclr $03,x,$04,loc_8AC6            ; 8ABE  1F 03 04 04   if tester_override_values .2 clear goto loc_8AC6
	ldab #$FF                           ; 8AC2  C6 FF         B = $FF(255)
	bra loc_8B0A                        ; 8AC4  20 44         goto loc_8B0A
loc_8AC6:
	clrb                                ; 8AC6  5F            B = 0
	bra loc_8B0A                        ; 8AC7  20 41         goto loc_8B0A
loc_8AC9:
	ldx #IOR_1807_MIL_RES_TRANSPU_IATPU ; 8AC9  CE 18 07      X = &IOR_1807_MIL_RES_TRANSPU_IATPU
	brclr $00,x,$10,loc_8AD3            ; 8ACC  1F 00 10 03   if IOR_1807_MIL_RES_TRANSPU_IATPU .4 clear goto loc_8AD3
	clrb                                ; 8AD0  5F            B = 0
	bra loc_8B0A                        ; 8AD1  20 37         goto loc_8B0A
loc_8AD3:
	ldx #PCS_clean_pulse_state          ; 8AD3  CE 1B BB      X = &PCS_clean_pulse_state | gear 0: force-motor cleaning pulse sequence, up to k_4AB7 ($FE) cycles in $1BBC
	ldaa >trans_gear_AT                 ; 8AD6  B6 1A C0      A = trans_gear_AT
	bne loc_8B30                        ; 8AD9  26 55         if A != 0 goto loc_8B30
	ldaa >PCS_clean_pulse_count         ; 8ADB  B6 1B BC      A = PCS_clean_pulse_count
	cmpa >k_PCS_clean_cycles_4AB7       ; 8ADE  B1 4A B7      compare A with k_PCS_clean_cycles_4AB7
	bhi loc_8B30                        ; 8AE1  22 4D         if PCS_clean_pulse_count > k_PCS_clean_cycles_4AB7 goto loc_8B30
	brclr $00,x,$03,loc_8AE9            ; 8AE3  1F 00 03 02   if PCS_clean_pulse_state .0,.1 clear goto loc_8AE9
	bra loc_8AEC                        ; 8AE7  20 03         goto loc_8AEC
loc_8AE9:
	bset $00,x,$01                      ; 8AE9  1C 00 01      [X+0] .0 = 1
loc_8AEC:
	brclr $00,x,$01,loc_8B0C            ; 8AEC  1F 00 01 1C   if [X+0] .0 clear goto loc_8B0C | phase A: duty 0 for kw_4AB8 ticks
	ldd >PCS_clean_pulse_timer          ; 8AF0  FC 1B BD      D = PCS_clean_pulse_timer
	cpd >kw_PCS_clean_low_ticks_4AB8    ; 8AF3  1A B3 4A B8   compare D with kw_PCS_clean_low_ticks_4AB8
	bcs loc_8B03                        ; 8AF7  25 0A         if PCS_clean_pulse_timer < kw_PCS_clean_low_ticks_4AB8 goto loc_8B03
	clra                                ; 8AF9  4F            A = 0
	clrb                                ; 8AFA  5F            B = 0
	bclr $00,x,$01                      ; 8AFB  1D 00 01      [X+0] .0 = 0
	bset $00,x,$02                      ; 8AFE  1C 00 02      [X+0] .1 = 1
	bra loc_8B06                        ; 8B01  20 03         goto loc_8B06
loc_8B03:
	addd #$0001                         ; 8B03  C3 00 01      D += $0001(1)
loc_8B06:
	std >PCS_clean_pulse_timer          ; 8B06  FD 1B BD      PCS_clean_pulse_timer = D
	clrb                                ; 8B09  5F            B = 0
loc_8B0A:
	bra loc_8B3C                        ; 8B0A  20 30         goto loc_8B3C
loc_8B0C:
	brclr $00,x,$02,loc_8B3C            ; 8B0C  1F 00 02 2C   if [X+0] .1 clear goto loc_8B3C | phase B: duty FF for kw_4ABA ticks, then count one cycle
	ldd >PCS_clean_pulse_timer          ; 8B10  FC 1B BD      D = PCS_clean_pulse_timer
	cpd >kw_PCS_clean_high_ticks_4ABA   ; 8B13  1A B3 4A BA   compare D with kw_PCS_clean_high_ticks_4ABA
	bcs loc_8B26                        ; 8B17  25 0D         if PCS_clean_pulse_timer < kw_PCS_clean_high_ticks_4ABA goto loc_8B26
	clra                                ; 8B19  4F            A = 0
	clrb                                ; 8B1A  5F            B = 0
	bclr $00,x,$02                      ; 8B1B  1D 00 02      [X+0] .1 = 0
	bset $00,x,$01                      ; 8B1E  1C 00 01      [X+0] .0 = 1
	inc >PCS_clean_pulse_count          ; 8B21  7C 1B BC      PCS_clean_pulse_count++
	bra loc_8B29                        ; 8B24  20 03         goto loc_8B29
loc_8B26:
	addd #$0001                         ; 8B26  C3 00 01      D += $0001(1)
loc_8B29:
	std >PCS_clean_pulse_timer          ; 8B29  FD 1B BD      PCS_clean_pulse_timer = D
	ldab #$FF                           ; 8B2C  C6 FF         B = $FF(255)
	bra loc_8B3C                        ; 8B2E  20 0C         goto loc_8B3C
loc_8B30:
	bclr $00,x,$03                      ; 8B30  1D 00 03      [X+0] .0,.1 = 0 | normal: duty = PCS_duty_cmd, reset pulse sequencer
	ldab >PCS_duty_cmd                  ; 8B33  F6 1A F7      B = PCS_duty_cmd
	clr >PCS_clean_pulse_timer          ; 8B36  7F 1B BD      PCS_clean_pulse_timer = 0
	clr >pcs_v1BBE                      ; 8B39  7F 1B BE      pcs_v1BBE = 0
loc_8B3C:
	stab >PCS_duty_out                  ; 8B3C  F7 1B AF      PCS_duty_out = B
	stab >$1809                         ; 8B3F  F7 18 09      PWM_PCS_control+1 = B | 1809 = TCC PWM solenoid duty (4L80E), see PWM_PCS_control note
	rts                                 ; 8B42  39            return

; ----------------------------------------------------------------------------
; calc_OLD_RPM2_4_8B43
;   analysis [low]: 50 ms: while fuel_quantity=0, [$B2] >= k_2755 and RPM above IDLE_SPEED_HIGH_BAND and $50,
;        counts RPM-rising samples (DELTA_RPM_COUNT), large RPM jumps >= kw_2757 ([$BD]) and trans slip ([$B9],
;        auto trans). Sets $54.2 when the counts pass the k_2752/k_2754/k_2756 limits, i.e. engine speed rising
;        with no fuel commanded (driveline-driven or runaway). Holds OLD_RPM2_4 as the previous RPM.
;   OBD1 L9E24 (match 1.00 p1-exact): seems related to engine shutdown of some kind... don't know what this does
;        yet.
;   inferred [B, pass A]: writes OLD_RPM2_4, DELTA_RPM_COUNT
;   called from: run_50ms_job
; ----------------------------------------------------------------------------
calc_OLD_RPM2_4_8B43:
	ldaa <closure_stale_ctr             ; 8B43  96 B2         A = closure_stale_ctr | only during zero fuel above idle band and $50 RPM byte (1500 rpm)
	cmpa >k_2755                        ; 8B45  B1 27 55      compare A with k_2755
	bcs loc_8B8E                        ; 8B48  25 44         if closure_stale_ctr < k_2755 goto loc_8B8E
	ldaa >fuel_quantity                 ; 8B4A  B6 19 A4      A = fuel_quantity
	bne loc_8B8E                        ; 8B4D  26 3F         if A != 0 goto loc_8B8E
	ldaa >engine_RPM                    ; 8B4F  B6 19 86      A = engine_RPM
	cmpa >IDLE_SPEED_HIGH_BAND          ; 8B52  B1 1C 64      compare A with IDLE_SPEED_HIGH_BAND
	bcs loc_8B8E                        ; 8B55  25 37         if engine_RPM < IDLE_SPEED_HIGH_BAND goto loc_8B8E
	cmpa >k_zero_fuel_rise_min_RPM_2753 ; 8B57  B1 27 53      compare A with k_zero_fuel_rise_min_RPM_2753 | kw_2753 is really a byte ($50) - used with cmpa | OBD1: set to $50
	bcs loc_8B8E                        ; 8B5A  25 32         if engine_RPM < k_zero_fuel_rise_min_RPM_2753 goto loc_8B8E
	ldd >engine_RPM                     ; 8B5C  FC 19 86      D = engine_RPM
	cpd <OLD_RPM2_4                     ; 8B5F  1A 93 B6      compare D with OLD_RPM2_4
	bcs loc_8B6F                        ; 8B62  25 0B         if engine_RPM < OLD_RPM2_4 goto loc_8B6F
	ldaa <DELTA_RPM_COUNT               ; 8B64  96 B8         A = DELTA_RPM_COUNT
	cmpa #$FF                           ; 8B66  81 FF         compare A with $FF(255)
	beq loc_8B76                        ; 8B68  27 0C         if DELTA_RPM_COUNT == $FF(255) goto loc_8B76
	inc >DELTA_RPM_COUNT                ; 8B6A  7C 00 B8      DELTA_RPM_COUNT++
	bra loc_8B76                        ; 8B6D  20 07         goto loc_8B76
loc_8B6F:
	ldaa <DELTA_RPM_COUNT               ; 8B6F  96 B8         A = DELTA_RPM_COUNT
	beq loc_8B76                        ; 8B71  27 03         if A == 0 goto loc_8B76
	dec >DELTA_RPM_COUNT                ; 8B73  7A 00 B8      DELTA_RPM_COUNT--
loc_8B76:
	ldd >engine_RPM                     ; 8B76  FC 19 86      D = engine_RPM | count big RPM jumps (>= kw_2757) in [$BD]
	subd <OLD_RPM2_4                    ; 8B79  93 B6         D -= OLD_RPM2_4
	bcs loc_8B90                        ; 8B7B  25 13         if D < 0 goto loc_8B90
	cpd >kw_2757                        ; 8B7D  1A B3 27 57   compare D with kw_2757 | OBD1: is set to $50
	bcs loc_8B90                        ; 8B81  25 0D         if D < kw_2757 goto loc_8B90
	ldaa <rpm_v00BD                     ; 8B83  96 BD         A = rpm_v00BD
	cmpa #$FF                           ; 8B85  81 FF         compare A with $FF(255)
	beq loc_8B93                        ; 8B87  27 0A         if rpm_v00BD == $FF(255) goto loc_8B93
	inc >rpm_v00BD                      ; 8B89  7C 00 BD      rpm_v00BD++
	bra loc_8B93                        ; 8B8C  20 05         goto loc_8B93
loc_8B8E:
	bra loc_8BD3                        ; 8B8E  20 43         goto loc_8BD3
loc_8B90:
	clr >rpm_v00BD                      ; 8B90  7F 00 BD      rpm_v00BD = 0
loc_8B93:
	ldx #Configuration_set              ; 8B93  CE 20 0B      X = &Configuration_set | OBD1: auto transmission flag
	brclr $00,x,$04,loc_8BA4            ; 8B96  1F 00 04 0A   if Configuration_set .2 TCM / no internal trans control clear goto loc_8BA4 | Configuration_set.2 (0x04) TCM/no-internal-trans flag | OBD1: BR IF NOT 4009.b2, BR IF auto
	ldaa <rpm_v00BD                     ; 8B9A  96 BD         A = rpm_v00BD
	cmpa >k_2756                        ; 8B9C  B1 27 56      compare A with k_2756
	bcs loc_8BA4                        ; 8B9F  25 03         if rpm_v00BD < k_2756 goto loc_8BA4
	jmp >loc_8C1B                       ; 8BA1  7E 8C 1B      goto loc_8C1B
loc_8BA4:
	brset $00,x,$04,loc_8BD6            ; 8BA4  1E 00 04 2E   if [X+0] .2 set goto loc_8BD6 | Configuration_set.2 (0x04) TCM/no-internal-trans flag: clr=check range 005F & 0x50 | OBD1: auto transmission flag
	ldaa <Cal_bit_6_store               ; 8BA8  96 5F         A = Cal_bit_6_store | OBD1: check for neutral
	anda #$50                           ; 8BAA  84 50         A &= $50(80) (keep bits)
	beq loc_8BB5                        ; 8BAC  27 07         if A == 0 goto loc_8BB5
	ldaa <DELTA_RPM_COUNT               ; 8BAE  96 B8         A = DELTA_RPM_COUNT
	cmpa >k_2756                        ; 8BB0  B1 27 56      compare A with k_2756
	bcc loc_8C1B                        ; 8BB3  24 66         if DELTA_RPM_COUNT >= k_2756 goto loc_8C1B
loc_8BB5:
	ldaa >TCC_slip_speed                ; 8BB5  B6 1B 01      A = TCC_slip_speed | auto trans: count slip events ([$1B01] > k_274E) in [$B9] | OBD1: transmission slip up/down counter
	bmi loc_8BD6                        ; 8BB8  2B 1C         if A < 0 (signed) goto loc_8BD6
	cmpa >k_274E                        ; 8BBA  B1 27 4E      compare A with k_274E | OBD1: is set to 03
	bhi loc_8BC8                        ; 8BBD  22 09         if TCC_slip_speed > k_274E goto loc_8BC8
	ldaa <rpm_v00B9                     ; 8BBF  96 B9         A = rpm_v00B9
	beq loc_8BD9                        ; 8BC1  27 16         if A == 0 goto loc_8BD9
	dec >rpm_v00B9                      ; 8BC3  7A 00 B9      rpm_v00B9--
	bra loc_8BD9                        ; 8BC6  20 11         goto loc_8BD9
loc_8BC8:
	ldaa <rpm_v00B9                     ; 8BC8  96 B9         A = rpm_v00B9
	cmpa #$FF                           ; 8BCA  81 FF         compare A with $FF(255)
	beq loc_8BD9                        ; 8BCC  27 0B         if rpm_v00B9 == $FF(255) goto loc_8BD9
	inc >rpm_v00B9                      ; 8BCE  7C 00 B9      rpm_v00B9++
	bra loc_8BD9                        ; 8BD1  20 06         goto loc_8BD9
loc_8BD3:
	clr >DELTA_RPM_COUNT                ; 8BD3  7F 00 B8      DELTA_RPM_COUNT = 0
loc_8BD6:
	clr >rpm_v00B9                      ; 8BD6  7F 00 B9      rpm_v00B9 = 0
loc_8BD9:
	ldd >engine_RPM                     ; 8BD9  FC 19 86      D = engine_RPM
