; ----------------------------------------------------------------------------
; calc_pulse_period_multi_96F9
;   analysis [medium]: OBD1 L8857: generic pulse-period calculator for a speed-input struct at Y (+0 last pulse
;        count, +1 last capture time, +3 hold counter, +4 period result, +6 new capture, +8 new count). With new
;        pulses it divides the capture-time delta by the pulse delta, scaled by B/X cal constants. With no new
;        pulses it keeps the old period for B cycles, then returns the default. Returns D = period.
;   OBD1 L8857 (match 1.00 p1-exact): Subroutine needed to process multiples of pulses...
;   called from: calc_input_shaft_speed_raw_9612, CALC_OSS_SPEED
; ----------------------------------------------------------------------------
calc_pulse_period_multi_96F9:
	ldaa $08,y                          ; 96F9  18 A6 08      A = [Y+8] | new pulses? if none, hold last period [Y+3] cycles before falling to default | OBD1: number of pulses
	suba $00,y                          ; 96FC  18 A0 00      A -= [Y+0]
	bne loc_9711                        ; 96FF  26 10         if A != 0 goto loc_9711
	ldab $03,y                          ; 9701  18 E6 03      B = [Y+3]
	beq loc_970C                        ; 9704  27 06         if B == 0 goto loc_970C
	decb                                ; 9706  5A            B--
	stab $03,y                          ; 9707  18 E7 03      [Y+3] = B
	bne loc_9745                        ; 970A  26 39         if B != 0 goto loc_9745
loc_970C:
	std $04,y                           ; 970C  18 ED 04      [Y+4] = D
	bra loc_9745                        ; 970F  20 34         goto loc_9745
loc_9711:
	pshb                                ; 9711  37            push B | period = capture-time delta / (pulse delta * scale), two-step FDIV
	ldab $03,y                          ; 9712  18 E6 03      B = [Y+3]
	beq loc_9732                        ; 9715  27 1B         if B == 0 goto loc_9732
	tab                                 ; 9717  16            B = A
	pshx                                ; 9718  3C            push X
	clra                                ; 9719  4F            A = 0
	asld                                ; 971A  05            D <<= 1
	asld                                ; 971B  05            D <<= 1
	asld                                ; 971C  05            D <<= 1
	pshb                                ; 971D  37            push B
	psha                                ; 971E  36            push A
	tsx                                 ; 971F  30            X = SP + 1
	asld                                ; 9720  05            D <<= 1
	addd $00,x                          ; 9721  E3 00         D += [X+0]
	ins                                 ; 9723  31            SP++
	ins                                 ; 9724  31            SP++
	pulx                                ; 9725  38            pop X
	fdiv                                ; 9726  03            X = (D << 16) / X (fraction)
	ldd $06,y                           ; 9727  18 EC 06      D = [Y+6]
	subd $01,y                          ; 972A  18 A3 01      D -= [Y+1]
	xgdx                                ; 972D  8F            swap D <-> X
	fdiv                                ; 972E  03            X = (D << 16) / X (fraction)
	stx $04,y                           ; 972F  CD EF 04      [Y+4] = X
loc_9732:
	ldx $06,y                           ; 9732  CD EE 06      X = [Y+6]
	stx $01,y                           ; 9735  CD EF 01      [Y+1] = X
	ldaa $08,y                          ; 9738  18 A6 08      A = [Y+8]
	staa $00,y                          ; 973B  18 A7 00      [Y+0] = A
	pula                                ; 973E  32            pop A
	staa $03,y                          ; 973F  18 A7 03      [Y+3] = A
	ldd $04,y                           ; 9742  18 EC 04      D = [Y+4]
loc_9745:
	rts                                 ; 9745  39            return

; ----------------------------------------------------------------------------
; calc_tp_for_transmission
;   analysis [high]: Builds the simulated throttle position engine_load_est_filtered (OBD1 SIM_TPS) for trans
;        control. With cruise not engaged it is the filtered pedal. Otherwise it interpolates the cruise fuel
;        request through Fuel_demand_map_0..3 vs CRUISE_RPM_CAP, clamps it at k_2090 and lag-filters it with
;        k_2095. The OBD1 notes in the source describe the equations.
;   OBD1 calc_tp_for_transmission (match 1.00 p1-exact): This is used for other control stuff but not the actual
;        sync
;   fuel quantity calculation.
;   Equation inputs are:
;   CFR = CRUISE_FUEL_REQ_NO_DERATE
;   IFR = IDLE_FUEL_REQ
;   AFR = APP_FUEL_REQ
;   ACF  = A
;   called from: run_25ms_job
; ----------------------------------------------------------------------------
calc_tp_for_transmission:
	ldaa >CRUISE_STATE                  ; 9746  B6 19 F0      A = CRUISE_STATE
	cmpa #$02                           ; 9749  81 02         compare A with 2
	bhi loc_9753                        ; 974B  22 06         if CRUISE_STATE > 2 goto loc_9753 | OBD1: BR IF CRUISE_STATE > 2
	ldaa >pedal_position_filtered       ; 974D  B6 19 16      A = pedal_position_filtered
	jmp >loc_9827                       ; 9750  7E 98 27      goto loc_9827 | OBD1: STORE SIM_TPS & rts
loc_9753:
	clra                                ; 9753  4F            A = 0
	brclr <ENGMODEFLAG,$40,loc_9765     ; 9754  13 4C 40 0D   if ENGMODEFLAG .6 idle mode clear goto loc_9765 | OBD1: in idle speed mode here
	ldab >IDLE_FUEL_REQ                 ; 9758  F6 1C 7F      B = IDLE_FUEL_REQ
	cmpb >APP_FUEL_REQ                  ; 975B  F1 19 AB      compare B with APP_FUEL_REQ
	bls loc_9765                        ; 975E  23 05         if IDLE_FUEL_REQ <= APP_FUEL_REQ goto loc_9765 | OBD1: BR IF IDLE_FUEL_REQ <= APP_FUEL_REQ
	cmpb >CRUISE_FUEL_REQ               ; 9760  F1 1A 15      compare B with CRUISE_FUEL_REQ | OBD1: already capped for derate
	bhi loc_979E                        ; 9763  22 39         if IDLE_FUEL_REQ > CRUISE_FUEL_REQ goto loc_979E | OBD1: BR IF IDLE_FUEL_REQ > CRUISE_FUEL_REQ
loc_9765:
	ldaa >pedal_position_filtered       ; 9765  B6 19 16      A = pedal_position_filtered
	cmpa #$DF                           ; 9768  81 DF         compare A with $DF(223)
	bcc loc_979E                        ; 976A  24 32         if pedal_position_filtered >= $DF(223) goto loc_979E | OBD1: BR IF APP_COND > 0xDF (87%)
	ldab >APP_FUEL_REQ                  ; 976C  F6 19 AB      B = APP_FUEL_REQ
	cmpb >CRUISE_FUEL_REQ               ; 976F  F1 1A 15      compare B with CRUISE_FUEL_REQ
	bhi loc_979E                        ; 9772  22 2A         if APP_FUEL_REQ > CRUISE_FUEL_REQ goto loc_979E | OBD1: BR IF APP_FUEL_REQ > CRUISE_FUEL_REQ

