;        |slip| goes to $1AFD. Flag $6A.5 is set when slip < kw_43A8 (-640) and cleared when slip > kw_43AA (+1),
;        so it means negative slip (coast or overrun).
;   inferred [B, pass A]: writes TCC_slip_speed, TCC_slip_abs
;   called from: Central_Scheduler
; ----------------------------------------------------------------------------
calc_TCC_slip_speed_B7F8:
	ldd >engine_speed_raw_trans         ; B7F8  FC 18 97      D = engine_speed_raw_trans
	subd >trans_v18A8                   ; B7FB  B3 18 A8      D -= trans_v18A8
	rora                                ; B7FE  46            A rotate right thru C
	rola                                ; B7FF  49            A rotate left thru C
	bvc loc_B809                        ; B800  28 07         if no overflow goto loc_B809
	ldd #$7FFF                          ; B802  CC 7F FF      D = $7FFF(32767)
	adcb #$00                           ; B805  C9 00         B += C + 0
	adca #$00                           ; B807  89 00         A += C + 0
