	ldx >TCC_slip_speed                 ; B81F  FE 1B 01      X = TCC_slip_speed | hysteresis: $6A.5 = negative slip (coast), set < kw_43A8, clear > kw_43AA
	cpx >kw_43A8                        ; B822  BC 43 A8      compare X with kw_43A8
	bge loc_B82C                        ; B825  2C 05         if X >= (signed) kw_43A8 goto loc_B82C
	bset <tcc_v006A,$20                 ; B827  14 6A 20      tcc_v006A .5 TC slip negative (coast), hysteresis = 1
	bra loc_B834                        ; B82A  20 08         goto loc_B834
