; ----------------------------------------------------------------------------
; calc_TCC_slip_integ_step_E351
;   analysis [medium]: Slip error = (|slip| $1AFD - target $1B11)/4, stored in $1B21 and clamped to -80..+240. It
;        is mapped to 0..255 ((e+80)*4/5) and looked up in t17_46DE to give the integrator step (D = 0:step). A
;        non-zero $1AE0 overrides the step.
;   called from: trans_line_pressure_calc, calc_TCC_PWM_slip_control_DFEA
; ----------------------------------------------------------------------------
calc_TCC_slip_integ_step_E351:
	ldd >TCC_slip_abs                   ; E351  FC 1A FD      D = TCC_slip_abs
	subd >TCC_slip_target               ; E354  B3 1B 11      D -= TCC_slip_target
	asra                                ; E357  47            A >>= 1 (signed)
	rorb                                ; E358  56            B rotate right thru C
	asra                                ; E359  47            A >>= 1 (signed)
	rorb                                ; E35A  56            B rotate right thru C
	std >TCC_slip_error_q4              ; E35B  FD 1B 21      TCC_slip_error_q4 = D
	cpd #$FFB0                          ; E35E  1A 83 FF B0   compare D with $FFB0(65456) | clamp slip error/4 to -80..+240, then map to 0..255 for the gain table
	bgt loc_E367                        ; E362  2E 03         if D > (signed) $FFB0(65456) goto loc_E367
	ldd #$FFB0                          ; E364  CC FF B0      D = $FFB0(65456)
loc_E367:
	cpd #$00F0                          ; E367  1A 83 00 F0   compare D with $00F0(240)
	blt loc_E370                        ; E36B  2D 03         if D < (signed) $00F0(240) goto loc_E370
	ldd #$00F0                          ; E36D  CC 00 F0      D = $00F0(240)
loc_E370:
	addd #$0050                         ; E370  C3 00 50      D += $0050(80)
	asld                                ; E373  05            D <<= 1
	asld                                ; E374  05            D <<= 1
	ldx #$0005                          ; E375  CE 00 05      X = $0005(5)
	idiv                                ; E378  02            X = D / X, D = remainder
	pshx                                ; E379  3C            push X
	pula                                ; E37A  32            pop A
	pulb                                ; E37B  33            pop B
	tsta                                ; E37C  4D            test A
	beq loc_E381                        ; E37D  27 02         if A == 0 goto loc_E381
	ldab #$FF                           ; E37F  C6 FF         B = $FF(255)
loc_E381:
	tba                                 ; E381  17            A = B
	psha                                ; E382  36            push A
	pula                                ; E383  32            pop A
	ldx #t17_TCC_slip_integ_gain_46DE   ; E384  CE 46 DE      X = &t17_TCC_slip_integ_gain_46DE
	jsr >lookup_2D_17pt_noheader        ; E387  BD 66 E5      A = 17pt lookup t17_TCC_slip_integ_gain_46DE[A]
	psha                                ; E38A  36            push A
	pulb                                ; E38B  33            pop B
	ldaa >tcc_v1AE0                     ; E38C  B6 1A E0      A = tcc_v1AE0 | nonzero $1AE0 overrides the table step
	beq loc_E392                        ; E38F  27 01         if A == 0 goto loc_E392
	tab                                 ; E391  16            B = A
loc_E392:
	clra                                ; E392  4F            A = 0
	bra loc_E395                        ; E393  20 00         goto loc_E395
loc_E395:
	rts                                 ; E395  39            return

