	ldab >trans_gear_AT                 ; E4BE  F6 1A C0      B = trans_gear_AT
	cmpb >k_num_shift_adapt_tables_3890 ; E4C1  F1 38 90      compare B with k_num_shift_adapt_tables_3890 | upshift tests only below top gear (k_3890 = 3 = 4th)
	bcc loc_E4D3                        ; E4C4  24 0D         if trans_gear_AT >= k_num_shift_adapt_tables_3890 goto loc_E4D3
	ldx #$1ABA                          ; E4C6  CE 1A BA      X = $1ABA(6842) | forced upshift request $1ABA[gear] takes priority
	abx                                 ; E4C9  3A            X += B
	ldaa $00,x                          ; E4CA  A6 00         A = [X+0]
	beq loc_E4D6                        ; E4CC  27 08         if A == 0 goto loc_E4D6
	bset <shift_request_reason,$08      ; E4CE  14 78 08      shift_request_reason .3 = 1
	bra loc_E50D                        ; E4D1  20 3A         goto loc_E50D
