	jsr >FETCH_VAL_USING_PRNDL          ; E4D9  BD EB CF      call FETCH_VAL_USING_PRNDL
	bcs loc_E4E3                        ; E4DC  25 05         if carry goto loc_E4E3
	bset <shift_request_reason,$04      ; E4DE  14 78 04      shift_request_reason .2 = 1
	bra loc_E50D                        ; E4E1  20 2A         goto loc_E50D
