; ----------------------------------------------------------------------------
; interp_4cell_by_temp_EAD6
;   analysis [medium]: Linear interpolation across a 4-cell array at X: A = input (trans temp), B = 3 segments.
;        A*3 high byte = cell index and low byte = fraction. Returns X[i] + (X[i+1]-X[i])*frac in A. Used to read
;        the adaptive shift-delay cells.
;   OBD1 LEFBE (match 0.93 p1-global)
;   called from: calc_upshift_RPM_projection_adapt_E8C2
; ----------------------------------------------------------------------------
interp_4cell_by_temp_EAD6:
	pshx                                ; EAD6  3C            push X
	pshb                                ; EAD7  37            push B
	mul                                 ; EAD8  3D            D = A * B | A*3: high byte = cell index 0..2, low byte = interpolation fraction
	pshb                                ; EAD9  37            push B
	tab                                 ; EADA  16            B = A
	abx                                 ; EADB  3A            X += B
	ldd $00,x                           ; EADC  EC 00         D = [X+0]
	sba                                 ; EADE  10            A -= B
	pulb                                ; EADF  33            pop B
	bcc loc_EAE8                        ; EAE0  24 06         if A >= 0 goto loc_EAE8
	nega                                ; EAE2  40            A = -A
	mul                                 ; EAE3  3D            D = A * B
	adca $00,x                          ; EAE4  A9 00         A += C + [X+0]
	bra loc_EAEE                        ; EAE6  20 06         goto loc_EAEE
loc_EAE8:
	mul                                 ; EAE8  3D            D = A * B
	adca #$00                           ; EAE9  89 00         A += C + 0
	nega                                ; EAEB  40            A = -A
	adda $00,x                          ; EAEC  AB 00         A += [X+0]
loc_EAEE:
	pulb                                ; EAEE  33            pop B
	pulx                                ; EAEF  38            pop X
	rts                                 ; EAF0  39            return

