; FETCH_VAL_USING_PRNDL
;   analysis [high]: If the PRNDL is in a manual range (L/2/3, Cal_bit_6_store b0-2) and the APP fault flag is
;        clear, it indexes the pointer table X by ((range>>1)*k_3890 + gear B)*2 and returns that byte in A with
;        C=0. Otherwise it returns A=0, C=1.
;   OBD1 FETCH_VAL_USING_PRNDL (match 0.96 p1-global)
;   called from: calc_shift_request_E4B2
; ----------------------------------------------------------------------------
FETCH_VAL_USING_PRNDL:
	pshb                                ; EBCF  37            push B
	brset <TRANS_FMEM_ENA_FLAGS,$04,loc_EBEE; EBD0  12 88 04 1A   if TRANS_FMEM_ENA_FLAGS .2 P1810 fault: force range = Drive 4 set goto loc_EBEE | OBD1: APP fault
	ldaa <Cal_bit_6_store               ; EBD4  96 5F         A = Cal_bit_6_store
	anda #$07                           ; EBD6  84 07         A &= 7 (keep bits) | OBD1: check for 3-2-1 position... if in one of those then we run this; if not, skip.
	beq loc_EBEE                        ; EBD8  27 14         if A == 0 goto loc_EBEE
	lsra                                ; EBDA  44            A >>= 1
	pshb                                ; EBDB  37            push B
	ldab >k_num_shift_adapt_tables_3890 ; EBDC  F6 38 90      B = k_num_shift_adapt_tables_3890
	mul                                 ; EBDF  3D            D = A * B
	pula                                ; EBE0  32            pop A
	aba                                 ; EBE1  1B            A += B
	asla                                ; EBE2  48            A <<= 1
	tab                                 ; EBE3  16            B = A
	abx                                 ; EBE4  3A            X += B
	ldx $00,x                           ; EBE5  EE 00         X = [X+0]
	beq loc_EBEE                        ; EBE7  27 05         if X == 0 goto loc_EBEE
	ldaa $00,x                          ; EBE9  A6 00         A = [X+0]
	clc                                 ; EBEB  0C            C = 0
	bra loc_EBF0                        ; EBEC  20 02         goto loc_EBF0
loc_EBEE:
	clra                                ; EBEE  4F            A = 0 | OBD1: in OD position
	sec                                 ; EBEF  0D            C = 1
loc_EBF0:
	pulb                                ; EBF0  33            pop B
	rts                                 ; EBF1  39            return

; ----------------------------------------------------------------------------
; select_ptr_by_gear_flags_EBF2
;   analysis [high]: OBD1 LA444. Searches a calibration pointer list: X[0]/X[1] give the flag mask and record
;        stride, B = gear, A = pattern flag byte. It walks the bits to find the first matching entry and returns X
;        = the pointer, with C=1 if there is no valid pointer.
;   OBD1 LA444 (match 1.00 p1-exact): This routine jumps around in a pointer table
;   with inputs:
;   B - Gear
;   A - Flag Byte (Actual inputs are L0037, L0038, L0039, L003A)
;   called from: calc_TCC_apply_speed_DBC6, calc_TCC_release_request_E20A, calc_shift_speed_load_based_EAF1, calc_shift_speed_fixed_EB47, calc_shift_RPM_target_EB8E
; ----------------------------------------------------------------------------
select_ptr_by_gear_flags_EBF2:
	pshb                                ; EBF2  37            push B | OBD1: push gear
	psha                                ; EBF3  36            push A | OBD1: 0 = Ai, 1 = Bi push flag
	ldaa $00,x                          ; EBF4  A6 00         A = [X+0] | OBD1: A = Xi[0]  get bit mask from calibration tables (usually $04)
	psha                                ; EBF6  36            push A | OBD1: 0 = Xi[0], 1 = Ai, 2 = Bi
	ldaa $01,x                          ; EBF7  A6 01         A = [X+1] | OBD1: A = Xi[1] (usually $08)
	psha                                ; EBF9  36            push A | OBD1: 0 = Xi[1], 1 = Xi[0], 2 = Ai, 3 = Bi
	aslb                                ; EBFA  58            B <<= 1 | OBD1: double gear and offset it
	abx                                 ; EBFB  3A            X += B | OBD1: X = Xi + 2 * Bi
	ldaa #$01                           ; EBFC  86 01         A = 1 | OBD1: A = 1  start with first bit...
	inx                                 ; EBFE  08            X++
	inx                                 ; EBFF  08            X++ | OBD1: X = Xi + 2 * Bi + 2
	pulb                                ; EC00  33            pop B | OBD1: B = Xi[1], 0 = Xi[0], 1 = Ai, 2 = Bi  get second bit mask value, what is it for? - maybe length of structure... looks right.
loc_EC01:
	pshx                                ; EC01  3C            push X | OBD1: 0:1 = (Xi + 2 * Bi + 2), 2 = Xi[0], 3 = Ai, 4 = Bi
	tsx                                 ; EC02  30            X = SP + 1
	bita $03,x                          ; EC03  A5 03         test A mask [X+3] | OBD1: as soon as bit is found then skip out
	bne loc_EC12                        ; EC05  26 0B         if any of mask [X+3] set goto loc_EC12 | OBD1: BR IF Ai & 1
	bita $02,x                          ; EC07  A5 02         test A mask [X+2] | OBD1: Check compare with flag bit
	bne loc_EC19                        ; EC09  26 0E         if any of mask [X+2] set goto loc_EC19 | OBD1: bit set? then get out
	asla                                ; EC0B  48            A <<= 1 | OBD1: A <<= 1
	bcs loc_EC19                        ; EC0C  25 0B         if A < 0 goto loc_EC19 | OBD1: done bit list (8 bits?) then get out
	pulx                                ; EC0E  38            pop X
	abx                                 ; EC0F  3A            X += B
	bra loc_EC01                        ; EC10  20 EF         goto loc_EC01 | OBD1: go back.....
loc_EC12:
	pulx                                ; EC12  38            pop X | OBD1: X = Pointer to Pointer, 0 = Xi[0], 1 = Ai, 2 = Bi
	ldx $00,x                           ; EC13  EE 00         X = [X+0] | OBD1: fetch pointer and check if valid
	beq loc_EC1A                        ; EC15  27 03         if X == 0 goto loc_EC1A
	bra loc_EC1D                        ; EC17  20 04         goto loc_EC1D
loc_EC19:
	pulx                                ; EC19  38            pop X
loc_EC1A:
	sec                                 ; EC1A  0D            C = 1 | OBD1: error flag - no pointer list found, skip function
	bra loc_EC1E                        ; EC1B  20 01         goto loc_EC1E
loc_EC1D:
	clc                                 ; EC1D  0C            C = 0
loc_EC1E:
	ins                                 ; EC1E  31            SP++ | OBD1: 0 = Ai, 1 = Bi
	pula                                ; EC1F  32            pop A | OBD1: get flag back
	pulb                                ; EC20  33            pop B | OBD1: get gear back
	rts                                 ; EC21  39            return

; ----------------------------------------------------------------------------
; blend_by_altitude_EC22
;   analysis [medium]: Not a DTC routine: '#DTC_P0602' is really the constant $51EB used as an fdiv divisor.
;        Weight = t17_389E[(18DE-$4000)/$51EB], where 18DE is a baro-derived value from B4BF. Returns A = A +
;        B*weight, with B a signed delta, clamped 0..255.
