; baro_from_MAP
;   analysis [medium]: Baro estimate from MAP (Turbo_ram_address*2). On NA engines (200C.6) or with the engine
;        stopped it uses MAP directly. On a running turbo engine it keeps min(baro, MAP) and fully re-learns from
;        MAP only after $5D.6 (low load) has held for k_baro_learn_loops (60) passes.
;   called from: run_100ms_engine_tasks_EC95
; ----------------------------------------------------------------------------
baro_from_MAP:
	ldaa >NA_ram_address                ; EE7D  B6 19 2F      A = NA_ram_address
	ldab >engine_RPM                    ; EE80  F6 19 86      B = engine_RPM
	beq loc_EEAF                        ; EE83  27 2A         if B == 0 goto loc_EEAF
	ldx #Configuration_set_2_200C       ; EE85  CE 20 0C      X = &Configuration_set_2_200C
	brset $00,x,$40,loc_EEAF            ; EE88  1E 00 40 23   if Configuration_set_2_200C .6 NA: baro = MAP set goto loc_EEAF | 200C.6 or engine stopped: baro = MAP*2, else min(baro,MAP) after 5D.6 held 31F5 loops
	ldab >Turbo_ram_address             ; EE8C  F6 19 23      B = Turbo_ram_address
	aslb                                ; EE8F  58            B <<= 1
	bcs loc_EEB7                        ; EE90  25 25         if B < 0 goto loc_EEB7
	cba                                 ; EE92  11            compare A with B
	blt loc_EE96                        ; EE93  2D 01         if A < (signed) B goto loc_EE96
	tba                                 ; EE95  17            A = B
loc_EE96:
	ldab <idle_v005D                    ; EE96  D6 5D         B = idle_v005D
	bitb #$40                           ; EE98  C5 40         test idle_v005D .6 idle governor fuel floor in control
	beq loc_EEAA                        ; EE9A  27 0E         if idle_v005D .6 idle governor fuel floor in control all clear goto loc_EEAA
	ldab >baro_learn_counter            ; EE9C  F6 1C 61      B = baro_learn_counter
	incb                                ; EE9F  5C            B++
	stab >baro_learn_counter            ; EEA0  F7 1C 61      baro_learn_counter = B
	cmpb >k_baro_learn_loops            ; EEA3  F1 31 F5      compare B with k_baro_learn_loops
	bcs loc_EEB7                        ; EEA6  25 0F         if baro_learn_counter < k_baro_learn_loops goto loc_EEB7
	bra loc_EEAF                        ; EEA8  20 05         goto loc_EEAF
