loc_FE0E:
	ldd >ref_period_filtered            ; FE0E  FC 19 54      D = ref_period_filtered
	asld                                ; FE11  05            D <<= 1
	bcs loc_FE2D                        ; FE12  25 19         if D < 0 goto loc_FE2D
	asld                                ; FE14  05            D <<= 1
	bcs loc_FE2D                        ; FE15  25 16         if D < 0 goto loc_FE2D
	asld                                ; FE17  05            D <<= 1
	bcs loc_FE2D                        ; FE18  25 13         if D < 0 goto loc_FE2D
