; boost_control
;   analysis [medium]: Wastegate PWM. Below RPM k_342D the duty is 0. Above it: boost target =
;        tbl3D_BOOST_target_RPM_x_Fuel_9x17_3450 + IAT adder ((IAT - k_34EB)/2, capped at k_34EA), stored in 1AB1.
;        Error vs Turbo_ram_address goes through P (DO_BOOST_PGAIN) and I (DO_BOOST_IGAIN) terms. Duty = high byte
;        of I +/- P, rounded. Boost sensor faults (0004 .4-.6) force k_3716 (0). Device-control override via 1CCC
;        (1CCA.5). O
;   called from: run_100ms_engine_tasks_EC95
; ----------------------------------------------------------------------------
boost_control:
	ldaa >engine_RPM                    ; FEAA  B6 19 86      A = engine_RPM
	cmpa >k_boost_ctrl_min_RPM_342D     ; FEAD  B1 34 2D      compare A with k_boost_ctrl_min_RPM_342D
	bhi loc_FEB5                        ; FEB0  22 03         if engine_RPM > k_boost_ctrl_min_RPM_342D goto loc_FEB5
	clra                                ; FEB2  4F            A = 0
	bra loc_FF17                        ; FEB3  20 62         goto loc_FF17
loc_FEB5:
	clr >BOOST_ERROR_SIGN               ; FEB5  7F 1A B3      BOOST_ERROR_SIGN = 0
	ldx #tbl3D_BOOST_target_RPM_x_Fuel_9x17_3450; FEB8  CE 34 50      X = &tbl3D_BOOST_target_RPM_x_Fuel_9x17_3450
	ldab >fuel_quantity                 ; FEBB  F6 19 A4      B = fuel_quantity
	jsr >lookup_3D_table                ; FEBE  BD 6D 20      A = 3D lookup tbl3D_BOOST_target_RPM_x_Fuel_9x17_3450[col A, row B]
	ldab >IAT_temp                      ; FEC1  F6 19 39      B = IAT_temp | IAT adder to boost target: (IAT - k_34EB)/2 capped at k_34EA (k_34EB=$DF so practically off)
	subb >k_34EB                        ; FEC4  F0 34 EB      B -= k_34EB
	bmi loc_FED3                        ; FEC7  2B 0A         if B < 0 (signed) goto loc_FED3
	lsrb                                ; FEC9  54            B >>= 1
	cmpb >k_34EA                        ; FECA  F1 34 EA      compare B with k_34EA
	bls loc_FED2                        ; FECD  23 03         if B <= k_34EA goto loc_FED2
	ldab >k_34EA                        ; FECF  F6 34 EA      B = k_34EA
loc_FED2:
