loc_FED3:
	staa >boost_target                  ; FED3  B7 1A B1      boost_target = A
	suba >Turbo_ram_address             ; FED6  B0 19 23      A -= Turbo_ram_address
	bcc loc_FEDF                        ; FED9  24 04         if A >= 0 goto loc_FEDF
	inc >BOOST_ERROR_SIGN               ; FEDB  7C 1A B3      BOOST_ERROR_SIGN++
