	pshb                                ; FEE5  37            push B
	psha                                ; FEE6  36            push A
	jsr >DO_BOOST_IGAIN                 ; FEE7  BD FF 45      call DO_BOOST_IGAIN
	tsx                                 ; FEEA  30            X = SP + 1
	tst >BOOST_ERROR_SIGN               ; FEEB  7D 1A B3      test BOOST_ERROR_SIGN
	beq loc_FEF9                        ; FEEE  27 09         if BOOST_ERROR_SIGN == 0 goto loc_FEF9
	subd $00,x                          ; FEF0  A3 00         D -= [X+0]
